	/* @Override */
	public void setFallThrough(Address addr) {
		if (SystemUtilities.isEqual(addr, getDefaultFallThrough())) {
			fallThroughOverride = null;
		}
		else if (addr == null) {
			fallThroughOverride = Address.NO_ADDRESS;
		}
		else {
			fallThroughOverride = addr;
		}
	}

